'''For a flat list of ephemerides generated by hdps.movers for one night,
interpolate the ephemerides to Argus image epochs (1 minute cadence).
'''

from argparse import ArgumentParser
import glob
import numpy as np
from numba import njit,prange
import pyarrow as pa
import pyarrow.compute as pc
import pyarrow.parquet as pq
import os

from hdps.skymap import TanSegmentLookup, SegmentationScheme


@njit
def spherical_to_cartesian(ra_deg,dec_deg):
    n_coord = len(ra_deg)
    x = np.empty(n_coord)
    y = np.empty(n_coord)
    z = np.empty(n_coord)
    for i in range(n_coord):
        ra_rad =np.deg2rad(ra_deg[i])
        dec_rad = np.deg2rad(dec_deg[i])
        x[i] = np.cos(ra_rad) * np.cos(dec_rad)
        y[i] = np.sin(ra_rad) * np.cos(dec_rad)
        z[i] = np.sin(dec_rad)
    return(x,y,z)

@njit
def cartesian_to_spherical(x,y,z):
    n_coord = len(x)
    ra_deg = np.empty(n_coord)
    dec_deg = np.empty(n_coord)
    for i in range(n_coord):
        r = np.sqrt((x[i]**2) + (y[i]**2) + (z[i]**2))
        ra_deg[i] = np.rad2deg(np.arctan2(y[i],x[i])) % 360
        dec_deg[i] = np.rad2deg(np.arcsin(z[i]/r))
    return(ra_deg,dec_deg)

@njit
def interp_object(target_epochs,obj_epochs,obj_ras,obj_decs,out_ra,out_dec):
    x,y,z = spherical_to_cartesian(obj_ras,obj_decs)
    x_interp = np.interp(target_epochs,obj_epochs,x)
    y_interp = np.interp(target_epochs,obj_epochs,y)
    z_interp = np.interp(target_epochs,obj_epochs,z)
    ra_interp,dec_interp = cartesian_to_spherical(x_interp,y_interp,z_interp)
    out_ra[:] = ra_interp
    out_dec[:] = dec_interp
    return(ra_interp,dec_interp)


@njit(parallel=True)
def interp_all(target_epochs,input_epochs,input_ras,input_decs,offsets,interpolated_ras,interpolated_decs):
    '''A function that interpolates the coordinates of all objects 
       at input epochs, to target epochs, in parallel.

       Arguments
       ---------
       target_epochs
       input_epochs
       input_ras
       input_decs
       offsets
       interpolated_ras
       interpolated_decs

       Returns
       -------
       out_ra: list[np.float64]
       out_dec: list[np.float64]
       
    '''
    n_objects = len(offsets)-1
    n_target_epochs = len(target_epochs)
    for i in prange(n_objects):
        in_start,in_end = offsets[i],offsets[i+1]
        out_start,out_end = i*n_target_epochs,(1+i)*n_target_epochs
        obj_epochs = input_epochs[in_start:in_end]
        obj_ras = input_ras[in_start:in_end]
        obj_decs = input_decs[in_start:in_end]
        out_ras = interpolated_ras[out_start:out_end]
        out_decs = interpolated_decs[out_start:out_end]
        interp_object(target_epochs,obj_epochs,obj_ras,obj_decs,out_ras,out_decs)
    return(interpolated_ras,interpolated_decs)


if __name__ == "__main__":

    # Input Arguments
    parser = ArgumentParser(description="For a catalog, count the minipix containing sources in each magnitude bin (0.5 mag).")
    parser.add_argument('--night',type=str,nargs=1,help="Night of sample ephemerides to interpolate, in format YYYY-MM-DD")
    args = parser.parse_args()

    # Get inputs

    # night
    night = args.night[0]


    # Setup
    #------

    # time and coordinate scales in input files:
    # time is in argus epoch microseconds, where argus epoch = seconds since 2025
    # coordinates are in mas 
    time_scale = 1_000_000.0
    coord_scale = 3_600_000.0

    # get location of night files
    night_inpath = "/net/scratch/dschlekat/ephemeris_samples3/" + night

    night_outpath = "/net/scratch/kmfas/ephem_samples_3/"

    # read in night files for objects(for making mag cut) & ephemerides (for interpolating)
    night_objects = pq.read_table(night_inpath+"/objects.parquet")
    night_ephems = pq.read_table(night_inpath+"/ephemerides.parquet")

    # make a cut on visual magnitude
    condish = pc.field("v_peak") <=20 #21.5
    night_objects_keep = night_objects.filter(condish)
    keep_desigs = pc.cast(night_objects_keep.column('designation'), pa.string())
    n_objects = len(keep_desigs)

    # get the ephemerides for objects that pass the mag cut
    ephem_desigs = pc.cast(night_ephems.column('designation'), pa.string())
    ephem_mask = pc.is_in(ephem_desigs,value_set=keep_desigs)
    night_ephems_keep = night_ephems.filter(ephem_mask)

    # get chunks (indices of where each grouped chunk of object ephemerides starts & ends)
    ephems_desigs_keep = pc.cast(night_ephems_keep.column('designation').combine_chunks(),pa.string())
    end_encodes = pc.run_end_encode(ephems_desigs_keep)  # get the last instance of each id, and the ids
    offsets = np.concatenate(([0],end_encodes.run_ends.to_numpy()))
    unique_desigs = end_encodes.values.to_numpy(zero_copy_only=False)

    # get target epochs (rough epochs of Argus images for 1 night, 1min cadence all night)
    night_props  = pq.read_table(night_inpath+"/properties.parquet")
    meta = night_props.schema.metadata # night interval lives in the metadata
    t0   = int(meta[b"t0_epoch_tt_us"]) # epoch in argus TT time in msec
    t1   = int(meta[b"t1_epoch_tt_us"])
    df   = night_props.to_pandas()
    target_epochs = np.arange(t0/1_000_000,(t1/1_000_000)+60.0,60.0)
    n_epochs = len(target_epochs)

    # format & scale intputs 
    in_epochs = night_ephems_keep.column("epoch_tt").combine_chunks().to_numpy().astype(np.float64) / time_scale
    in_ras = night_ephems_keep.column("ra").combine_chunks().to_numpy().astype(np.float64)/coord_scale
    in_decs = night_ephems_keep.column("dec").combine_chunks().to_numpy().astype(np.float64)/coord_scale

    # built output structures
    interped_ras = np.empty(n_objects*n_epochs,dtype=np.float64)
    interped_decs = np.empty(n_objects*n_epochs,dtype=np.float64)


    # Interpolate
    #------------
    interp_all(target_epochs,in_epochs,in_ras,in_decs,offsets,interped_ras,interped_decs)

    # get tile & minipix ids
    lookup = TanSegmentLookup(
        spacing_deg=(SegmentationScheme.DEFAULT_TILE_SIZE_ARCSEC-SegmentationScheme.DEFAULT_OVERLAP_ARCSEC)/3600.0,
        pixel_scale_deg=SegmentationScheme.DEFAULT_PIXEL_SCALE/3600.0,
        dec_min=-90.0,
        ra_min=0.0,
    )
    tile_ids,minipix_idxs = lookup.query_batch(interped_ras,interped_decs)

    # rescale epochs and coordinates
    target_epochs_usec = (target_epochs * time_scale).astype(np.int64) # to int64
    target_ras_mas = (interped_ras * coord_scale).astype(np.int32) # to int32
    target_decs_mas = (interped_decs * coord_scale).astype(np.int32)

    # build output table
    desigs_full = np.repeat(unique_desigs,n_epochs)
    target_epochs_full = np.tile(target_epochs_usec,n_objects)

    interpolated_output = pa.table({
        "designation": desigs_full,
        "epoch_tt": target_epochs_full,
        "ra": target_ras_mas,
        "dec": target_decs_mas,
        "tile_id": tile_ids,
        "minipix_idx": minipix_idxs,
    })

    # save interpolated positions
    night_combined = "".join(night.split("-"))
    pq.write_table(interpolated_output,
                   night_outpath+"/"+night_combined+"_sso_detections.parquet",
                   compression="zstd",
                   compression_level=3,
                   use_dictionary=["designation"],
                   column_encoding={
                       "ra": "DELTA_BINARY_PACKED",
                       "dec": "DELTA_BINARY_PACKED",
                       "epoch_tt": "DELTA_BINARY_PACKED",
                       "tile_id": "DELTA_BINARY_PACKED",
                       "minipix_idx": "DELTA_BINARY_PACKED",
                    },
                   )

    # Get minipixes
    #--------------

    # Get, for each object, then each unique minipix the object appears in, 
    # the first and last epoch that the object is in the minipix.  
    # This is not a list of completely unique minipix with all 
    # start/durations, it's just a per-object unique minipix list
    visits = interpolated_output.group_by(['designation','tile_id','minipix_idx']).aggregate([('epoch_tt','min'),('epoch_tt','max')])

    # Get a column of durations for each object's appearance in a minpix, noting:
    # "A minipix is considered "active" at time T if T falls within any [start, start + duration) interval"
    # ^ https://github.com/argus-hdps/hdps/blob/f264c9c7cba7719846668c95bdab77bcac5c9319/docs/source/technotes/0001-image-format.rst#L381 
    # so I add 1 min to each, since the end of the duration is not inclusive
    visits = visits.append_column("active_duration",[(visits.column('epoch_tt_max').to_numpy()-visits.column("epoch_tt_min").to_numpy())+(60*np.int64(time_scale))])
    visits = visits.rename_columns({"epoch_tt_min": "active_start_tt"})
    visits = visits.drop("epoch_tt_max")


    # save per-object minipix visits: 
    pq.write_table(visits.sort_by([("designation","ascending"),("active_start_tt","ascending")]),
                   night_outpath+"/"+night_combined+"_sso_minipix_visits.parquet",
                   compression="zstd",
                   compression_level=3,
                   use_dictionary=["designation"],
                   column_encoding={
                       "tile_id": "DELTA_BINARY_PACKED",
                       "minipix_idx": "DELTA_BINARY_PACKED",
                       "active_start_tt": "DELTA_BINARY_PACKED",
                       "active_duration": "DELTA_BINARY_PACKED",
                    },
                   )